import { EdkValidationError } from "../../../elementum-entity-client/errors.js";
/** Mark an explicit platform user id. Prefer a portable user reference when one is available. */
export function userId(value) {
    if (value.trim() === "")
        throw new EdkValidationError("userId requires a non-empty platform id.");
    return value;
}
/** Mark an explicit platform group id. Prefer an `org.groups.*` token when one is available. */
export function groupId(value) {
    if (value.trim() === "")
        throw new EdkValidationError("groupId requires a non-empty platform id.");
    return value;
}
